;
; .resource_load_to_ram_fail:
;     pop de
;     ret
;
; ; ------------------------------------------------------------------
; ; resource_load_to_vram_by_id
; ; Inputs:
; ;   A  = resource id
; ;   DE = destination in VRAM
; ; Outputs:
; ;   carry clear on success
; ;   carry set if resource id is missing
; ; Clobbers:
; ;   AF, BC, DE, HL
; ; ------------------------------------------------------------------
; resource_load_to_vram_by_id:
