; ;   carry set if resource id is missing
; ; Notes:
; ;   Keeps the current screen's immutable effect zone table resident in RAM.
; ; Clobbers:
; ;   AF, BC, DE, HL
; ; ------------------------------------------------------------------
; resource_load_effect_zone_table_cached:
