;     ld a, (resource_ram_cache_effect_zone_table_id)
;     cp c
;     jr z, .resource_effect_zone_cache_hit
;     push bc
;     ld a, c
;     ld de, runtime_effect_zone_table
;     call resource_load_to_ram_by_id
