; [[[MIDEAS_ARTIFACT:world_music_policy.txt:BEGIN]]]
; WORLD MUSIC POLICY
; Source: inferred from Game Flow paths reaching each WorldLink.
; Mode preserve: multiple different music states can reach the same world.
;
