; PACKS
; PACK 00 default
; - display: Default runtime sprite set
; - slots: 1/64
; - placeholder_slot: 0
; - sprites: none
;
; WORLD -> PACK
; 00 default -> default [id=0]
; [[[MIDEAS_ARTIFACT:world_sprite_pattern_policy.txt:END]]]

