; ==================================================================
; INIT_GAME_SYSTEMS — in bank 0 so it is reachable from any bank
; Calls routines in statically-mapped primary banks (1-2) via CALL.
; Routines in far banks are called via _far trampolines above.
; ==================================================================
init_game_systems:
    call DISSCR               ; Disable screen while loading VRAM assets
    ; Cold boot / restart must not trust cached VRAM state from RAM contents.
    xor a
    ld (vram_cache_tile_patterns_ready), a
    ld (vram_cache_tile_colors_ready), a
    ld (vram_cache_font_ready), a
    ld a, #FF
    ld (current_screen2_tilebank_id), a
    ; No entities - skipping component system initialization

    ; Load shared gameplay pattern/color data once unless VRAM was invalidated.
    call load_patterns_to_vram_far
    call load_colors_to_vram_far

    ; Initialize animated tile runtime (safe no-op if no animated groups)
    call init_animated_tiles_far
    ; Initialize boss runtime
    call init_boss_system_far


    ; No entities to initialize

    ; No screens - skip screen loading

    ; No text/menus - skip font initialization
    call ENASCR               ; Re-enable screen after VRAM updates
    ret

load_game_screen:
    ret

init_font_system:
    ret


; --- End of Bank 0 — pad to 8KB boundary ---
BANK_0_USED_END:
    ds #6000 - $, #FF

; ##################################################################
; BANK 1 — [#6000h-#8000h] PRIMARY: components
; (Always mapped at boot: bank1→P1, bank2→P2)
; ##################################################################
    org #6000

; @mideas:block id=runtime.components.stub kind=routine owner=components preserve=true roots=compatibility-stubs
; ==================================================================
; GAME COMPONENT SYSTEMS(SKIPPED - NO ENTITIES DETECTED)
    ; File: components.asm
        ; ==================================================================

; No entities detected in project - ECS system not needed
    ; This saves ~650 lines of unused component management code

; Constants required by state machine action handlers
ANIM_FLAG_PLAYING            EQU #01
ANIM_FLAG_LOOP               EQU #02
ANIM_FLAG_ONLY_WHEN_MOVING   EQU #04
ANIM_FLAG_COMPLETED          EQU #08
ANIM_FLAG_FORCE_UPLOAD       EQU #10
ANIM_DEFAULT_SPEED           EQU 8

COMP_POSITION   EQU 0
COMP_SPRITE     EQU 1
COMP_MOVEMENT   EQU 2
COMP_COLLISION  EQU 3
COMP_INPUT      EQU 4
COMP_BEHAVIOR   EQU 5
COMP_HEALTH     EQU 6
COMP_ANIMATION  EQU 7
COMP_JUMP       EQU 8
COMP_GRAVITY    EQU 9
COMP_DEADLY_TILES EQU 13

COMP_MASK_POSITION   EQU #0001
COMP_MASK_SPRITE     EQU #0002
COMP_MASK_MOVEMENT   EQU #0004
COMP_MASK_COLLISION  EQU #0008
COMP_MASK_INPUT      EQU #0010
COMP_MASK_BEHAVIOR   EQU #0020
COMP_MASK_HEALTH     EQU #0040
COMP_MASK_ANIMATION  EQU #0080
COMP_MASK_JUMP       EQU #0100
COMP_MASK_GRAVITY    EQU #0200
COMP_MASK_AUTO_DESTROY EQU #0400
COMP_MASK_DAMAGE     EQU #0800
COMP_MASK_SHOOT      EQU #1000
COMP_MASK_DEADLY_TILES EQU #2000
COMP_MASK_WALL_JUMP EQU #4000
COMP_MASK_AIR_CONTROL EQU #8000

COMP_TRIGGER_FIRE    EQU 0
COMP_TRIGGER_ACTION2 EQU 1
COMP_TRIGGER_UP      EQU 2

    ; Minimal stub functions for compatibility
init_components:
    ret
init_entities:
    ret
update_all_entities:
    ret

; [PLAYER FASTPATH / STATE MACHINE EXECUTOR moved to components_tail resident module]


; --- End of Bank 1 — pad to 8KB boundary ---
BANK_1_USED_END:
    ds #8000 - $, #FF

; ##################################################################
; BANK 2 — [#8000h-#A000h] PRIMARY: components_tail
; (Always mapped at boot: bank1→P1, bank2→P2)
; ##################################################################
    org #8000

; ==================================================================
; COMPONENTS RESIDENT TAIL
; Split from components.asm so the always-mapped P1 component core stays
; within one 8KB Konami/ASCII8 bank while tail routines run from P2.
; ==================================================================
update_player_fastpath:
    ret
execute_all_state_machines:
    ret
refresh_player_deadly_fastpath:
    ret
refresh_player_tile_interaction_fastpath:
    ret
refresh_player_state_machine_fastpath:
    ret
refresh_player_wallgrab_fastpath:
    ret
refresh_player_animation_fastpath:
    ret
refresh_player_sprite_fastpath:
    ret
create_entity:
    ret
entity_job_set:
    ret
entity_job_should_run_c:
    ld a, 1
    ret
force_update_entity_sprite:
    ret

mark_used_entity_list_dirty:
    ld hl, active_entity_list_dirty
    ld (hl), 1
    ret

ensure_used_entity_list_current:
    call call_rebuild_used_entity_list_resident
    ret

rebuild_used_entity_list:
    xor a
    ld (active_entity_count), a
    ld (input_entity_count), a
    ld (render_entity_count), a
    ld (collision_entity_count), a
    ld (ground_entity_count), a
    ld (anim_entity_count), a
    ld (coll_list_count), a
    ld (active_entity_list_dirty), a
    ld a, #FF
    ld (hero_entity_id), a
    ret

